Here's my patch, but I'll submit a PR shortly:

``` diff
diff --git a/src/Symfony/Component/Yaml/Parser.php b/src/Symfony/Component/Yaml/Parser.php
index d09227b..53a9a6b 100644
--- a/src/Symfony/Component/Yaml/Parser.php
+++ b/src/Symfony/Component/Yaml/Parser.php
@@ -186,8 +186,9 @@ class Parser
                     }
                 }
             } else {
-                // 1-liner followed by newline
-                if (2 == count($this->lines) && empty($this->lines[1])) {
+                // 1-liner optionally followed by newline
+                $lineCount = count($this->lines);
+                if (1 === $lineCount || (2 === $lineCount && empty($this->lines[1]))) {
                     try {
                         $value = Inline::parse($this->lines[0]);
                     } catch (ParseException $e) {
@@ -544,10 +545,6 @@ class Parser
     {
         $value = str_replace(array("\r\n", "\r"), "\n", $value);

-        if (!preg_match("#\n$#", $value)) {
-            $value .= "\n";
-        }
-
         // strip YAML header
         $count = 0;
         $value = preg_replace('#^\%YAML[: ][\d\.]+.*\n#su', '', $value, -1, $count);
